$rows=$pdo->query('SELECT * FROM productos ORDER BY nombre')->fetchAll();head('Productos');
?><div class="card card-body mb-3"><h2 class="h5">Nuevo producto</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-2"><div class="col-md-2"><input name="sku" class="form-control" placeholder="SKU"></div><div class="col-md-2"><input name="no_identificacion" class="form-control" placeholder="No. identificación"></div><div class="col-md-4"><input name="nombre" class="form-control" placeholder="Nombre" required></div><div class="col-md-2"><input name="categoria" class="form-control" placeholder="Categoría"></div><div class="col-md-2"><input name="unidad" class="form-control" placeholder="Unidad"></div><div class="col-md-2"><input name="marca" class="form-control" placeholder="Marca"></div><div class="col-md-2"><input name="costo" type="number" step=".0001" class="form-control" placeholder="Costo" value="0"></div><div class="col-md-2"><input name="venta" type="number" step=".0001" class="form-control" placeholder="Venta" value="0"></div><div class="col-md-2"><input name="stock" type="number" step=".001" class="form-control" placeholder="Stock" value="0"></div><div class="col-md-2"><input name="min_stock" type="number" step=".001" class="form-control" placeholder="Stock mínimo" value="0"></div><div class="col-md-8"><input name="descripcion" class="form-control" placeholder="Descripción"></div><div class="col-md-2"><button class="btn btn-primary w-100">Agregar</button></div></div></form></div><div class="card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>SKU</th><th>Producto</th><th>Categoría</th><th>Marca</th><th>Costo</th><th>Venta</th><th>Stock</th><th>Activo</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['sku'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['categoria'])?></td><td><?=e($r['marca'])?></td><td><?=money($r['costo_actual'])?></td><td><?=money($r['precio_venta'])?></td><td><?=e($r['stock'])?></td><td><?=((int)$r['activo']?'Sí':'No')?></td></tr><?php endforeach?></tbody></table></div></div></div><?php foot();
